input.command:
uv run python - <<'EOF'
from vela.domain.catalog import load_fixture
from collections import Counter
for f in ("fixtures/catalog.json","fixtures/catalog-staging.json"):
    ps=[p for p in load_fixture(f) if not p.archived]
    print(f, Counter(p.category for p in ps))
    for p in ps:
        if "gift" in p.slug or "gift" in p.title.lower() or p.destination=="Weebora":
            print("  gift?", p.id, p.slug, p.title, p.destination, p.category)
EOF

